L1: import { spawn } from "node:child_process";
L2: import { hasCredential, hooksDisabled, hooksDryRun, dontLog } from "../tools/ambient.mjs";
L3: // SessionEnd / close hook: file the unit that just finished, the way Cursor's installed hooks do.
L4: //
L5: // Cursor has had this pair all along (sessionStart -> `centricmem ambient --write`, sessionEnd ->
L6: // `centricmem log-session --auto`). This is the same second half for the clients whose lifecycle events
L7: // include SessionEnd: Claude Code and Codex both do, and Codex's own documentation puts it as "when the main
L8: // thread ends, doesn't run for subagents" - once per session, not once per turn.
L9: //
L10: // Rules, same as the ambient hooks: never fail, and say nothing when there is nothing to say. A close hook
L11: // that exits non-zero can break somebody's session end, and one that runs on every turn would file a card
L12: // per turn, which is why Stop is deliberately not used here.
L13: //
L14: // Filing the session is the point of the product, so this does not ask permission - but it does honour the
L15: // switches mimocode documents (CENTRICMEM_HOOK_DISABLE, CENTRICMEM_DONT_LOG, CENTRICMEM_HOOK_DRY_RUN), so a
L16: // user who set one does not get a different answer on the next host along.
L17: //
L18: // The child is spawned detached and unref'd, as the dsh close-half does: filing is allowed to take its time,
L19: // but the session must not sit waiting for it. Diagnostics go to stderr, because on goose stdout is the
L20: // hook decision channel and a stray line there reads as a decision.
L21: 
L22: const TIMEOUT_MS = 20000;
L23: 
L24: const run = (args) => {
