L26:   try {
L27:     // On Windows the CLI arrives as a .cmd shim, and a .cmd spawned with shell:false throws EINVAL - which
L28:     // the catch below swallows, so the hook looked silent and healthy while doing nothing (seen on dsh and
L29:     // on Claude Code). shell on Windows only, with a fixed argument list.
L30:     const exe = process.platform === "win32" ? "centricmem.cmd" : "centricmem";
L31:     child = spawn(exe, args, {
L32:       detached: true,
L33:       stdio: "ignore",
L34:       shell: process.platform === "win32",
L35:       windowsHide: true,
L36:     });
L37:   } catch {
L38:     return;
L39:   }
