L109:  *
L110:  * The CLI is not an option on a guest host: `centricmem done` writes a local hub
L111:  * file and refuses by design, even with a token and CENTRICMEM_HOME unset. The MCP
L112:  * endpoint is the write path that works, and a plugin can speak it directly -
L113:  * initialize, initialized, tools/call.
L114:  *
L115:  * Bounded and awaited. A hook has 5000ms before MiMoCode rolls the output back and
L116:  * counts a failure toward the 3-strike circuit breaker, so this has to return on
L117:  * its own; the abort controller guarantees that even if the network stalls.
L118:  */
L119: async function closeViaMcp(shelf: string, summary: string): Promise<number> {
L120:   const token = readToken();
L121:   if (!token) { trace("close skipped: no credential"); return 0; }
L122: 
L123:   const endpoint =
L124:     (process.env.CENTRICMEM_URL || "https://mem.centricmem.com").replace(/\/$/, "") + "/mcp";
L125:   const ac = new AbortController();
L126:   const timer = setTimeout(() => ac.abort(), 3500);
L127:   const headers: Record<string, string> = {
L128:     authorization: "Bearer " + token,
L129:     "content-type": "application/json",
L130:     accept: "application/json, text/event-stream",
L131:   };
L132: 
L133:   try {
L134:     const init = await fetch(endpoint, {
L135:       method: "POST",
L136:       headers,
L137:       signal: ac.signal,
L138:       body: JSON.stringify({
L139:         jsonrpc: "2.0",
L140:         id: 1,
L141:         method: "initialize",
L142:         params: {
L143:           protocolVersion: "2025-06-18",
L144:           capabilities: {},
L145:           clientInfo: { name: "centricmem-mimocode", version: "1.0" },
L146:         },
L147:       }),
L148:     });
L149:     const sid = init.headers.get("mcp-session-id");
L150:     await init.text();
L151:     if (sid) headers["mcp-session-id"] = sid;
L152: 
L153:     await fetch(endpoint, {
L154:       method: "POST",
L155:       headers,
L156:       signal: ac.signal,
L157:       body: JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }),
L158:     }).then((r) => r.text()).catch(() => "");
